-- CI-042 v2.2 MANDATORY PRE-CHECK (read-only). Apply ONLY if every row has pass = true. Baseline literals: production 27 Oct 2026 17:00 IST.
with cols as (select c.oid::regclass::text v, string_agg(a.attnum||':'||a.attname||':'||format_type(a.atttypid,a.atttypmod), ',' order by a.attnum) s
                from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
               where c.oid in ('costing.v_costing_period_run_status'::regclass,'public.v_costing_pricing_period_run_status'::regclass) group by 1),
chk(check_name, expected, actual) as (
  select 'P01 combined fingerprint 119/122/143', '3e5515ed97189b747ea3a8d18c3f4411', (select md5(string_agg(md5(costing.fn_compute_run_fingerprint(r)::text),'|' order by r)) from unnest(array[119,122,143]) r)
  union all select 'P02 queued/running runs', '0', (select count(*)::text from costing.costing_refresh_run where overall_status in ('QUEUED','RUNNING'))
  union all select 'P03 runs count/max', '118/143', (select count(*)||'/'||max(id) from costing.costing_refresh_run)
  union all select 'P04 audit rows count/max id', '17/21', (select count(*)||'/'||max(audit_id) from costing.cost_period_governance_audit)
  union all select 'P05 designation rows count/max id', '9/11', (select count(*)||'/'||max(id) from costing.costing_run_designation)
  union all select 'P06 fingerprint rows count/max id', '28/30', (select count(*)||'/'||max(id) from costing.costing_run_fingerprint)
  union all select 'P07 effective designations', '119=REFERENCE,122=APPROVED,128=REVOKED,136=REVOKED,140=REVOKED,143=APPROVED', (select string_agg(refresh_run_id||'='||designation, ',' order by refresh_run_id) from costing.v_costing_run_effective_designation)
  union all select 'P08 periods', '2026-03-01:OPEN:2026-03-31 2026-06-01:OPEN:2026-06-30 2026-07-01:OPEN:2026-07-22 2026-08-01:OPEN:2026-08-07 2026-09-01:LOCKED:2026-09-10 2026-10-01:OPEN:2026-10-22', (select string_agg(period_start||':'||status||':'||valuation_date, ' ' order by period_start) from costing.cost_periods)
  union all select 'P09 md5 rpc_costing_lock_period', '95612aa456e70d22217329ab294f54fa', md5(pg_get_functiondef('public.rpc_costing_lock_period(date,text,text)'::regprocedure))
  union all select 'P10 md5 rpc_costing_finalize_monthend_run', '1b221c05fbd65fd0c9246d73de6f0204', md5(pg_get_functiondef('public.rpc_costing_finalize_monthend_run(bigint,text,text)'::regprocedure))
  union all select 'P11 md5 views costing/public status', 'd38be6e4c0c8bb9811f4872b78e72936,490345425d4204741d52b8ca70fbbcb3', md5(pg_get_viewdef('costing.v_costing_period_run_status'::regclass))||','||md5(pg_get_viewdef('public.v_costing_pricing_period_run_status'::regclass))
  union all select 'P12 CI-040 dependency fn_w2_approve_unified present', 'true', (to_regprocedure('costing.fn_w2_approve_unified(bigint,text,text,bigint,boolean,text)') is not null)::text
  union all select 'P13 ACL lock / finalise', '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres} | {postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}', (select proacl::text from pg_proc where oid='public.rpc_costing_lock_period(date,text,text)'::regprocedure)||' | '||(select proacl::text from pg_proc where oid='public.rpc_costing_finalize_monthend_run(bigint,text,text)'::regprocedure)
  union all select 'P14 ACL status views costing | public', '{postgres=arwdDxtm/postgres,service_role=r/postgres} | {postgres=arwdDxtm/postgres,authenticated=r/postgres,service_role=arwdDxtm/postgres}', (select relacl::text from pg_class where oid='costing.v_costing_period_run_status'::regclass)||' | '||(select relacl::text from pg_class where oid='public.v_costing_pricing_period_run_status'::regclass)
  union all select 'P15 status view columns (18, both views identical)', '1:period_start:date,2:period_status:text,3:valuation_date:date,4:valuation_date_status:text,5:displayed_run_id:bigint,6:displayed_run_basis:text,7:approved_run_id:bigint,8:approved_at:timestamp with time zone,9:approved_by:text,10:latest_success_run_id:bigint,11:latest_success_finished_at:timestamp with time zone,12:newer_draft_run_id:bigint,13:active_run_id:bigint,14:active_run_status:text,15:active_run_stage:text,16:display_state:text,17:display_label:text,18:is_latest_approved_period:boolean x2', (select max(s)||' x'||count(distinct v) from cols having count(distinct s)=1)
  union all select 'P16 CI-042 new objects absent', '', concat_ws(',', to_regprocedure('public.rpc_costing_lock_periods_for_close(date[],text,text)'), to_regprocedure('public.rpc_costing_finalize_monthend_run_with_preview(bigint,text,text,bigint,boolean)'), to_regclass('costing.v_costing_run_display_status'), to_regclass('public.v_costing_pricing_run_display_status'))
  union all select 'P17 cron 66/67/68 active + command md5', '66:true:0045bba6068cf31ac53852d6b743a745 67:true:0045bba6068cf31ac53852d6b743a745 68:true:c3b74bfc510dd2b4dc061217ff43eef6', (select string_agg(jobid||':'||active||':'||md5(command), ' ' order by jobid) from cron.job where jobid in (66,67,68))
)
select check_name, expected, actual, coalesce(expected = actual, false) pass from chk
union all select 'ALL PRE-CHECKS PASS', 'true', (select bool_and(coalesce(expected=actual,false))::text from chk), (select bool_and(coalesce(expected=actual,false)) from chk);
